<script setup lang="ts">
defineProps<{ traces: Record<string, any>[] }>()
function text(value: unknown) { return JSON.stringify(value, null, 2) }
function parsed(message: Record<string, any>) { try { return typeof message.content === 'string' ? JSON.parse(message.content) : message.content } catch { return null } }
function roleName(role: string) { return ({ system: '系统上下文', user: '用户输入', assistant: '助手内容', tool: '工具结果' } as Record<string, string>)[role] || role || '未知角色' }
function sourceText(message: Record<string, any>) { const content = parsed(message); if (content && Array.isArray(content.segments)) return content.segments.map((segment: any) => segment.text || `[${segment.type}]`).join(''); return typeof message.content === 'string' ? message.content : text(message.content) }
</script>
<template>
  <section class="panel trace-inspector"><h3>模型调用诊断</h3><p class="muted">显示运行时记录的触发轮次、输入上下文、素材归属与决策。</p>
    <article v-for="trace in traces" :key="trace.id" class="trace-card"><header><div><b>{{trace.decision?.reason||trace.type||'调用记录'}}</b><p>{{trace.createdAt||'时间未知'}} · 会话 {{trace.chatId||'未知'}} · 触发 {{trace.triggerId||'未知'}}</p></div><code>{{trace.id}}</code></header>
      <div class="trace-grid"><section><h4>模型输入 · {{trace.messages?.length||0}} 条</h4><article v-for="(message,index) in trace.messages||[]" :key="`${index}-${message.role}-${message.content}`" class="context-message"><div class="context-heading"><b>{{roleName(message.role)}}</b><span v-if="parsed(message)?.relation" class="relation-pill">{{parsed(message).relation}}</span></div><template v-if="parsed(message)?.segments"><div v-for="(segment,segmentIndex) in parsed(message).segments" :key="segmentIndex" class="context-segment"><p>{{segment.text||`[${segment.type}]`}}</p></div><small>消息 {{parsed(message).messageId||'未知'}} · {{parsed(message).senderName||parsed(message).senderId||'来源未知'}} · {{parsed(message).sentAt||'时间未知'}}</small></template><p v-else class="context-content">{{sourceText(message)}}</p><details class="raw-context"><summary>查看原始输入</summary><pre>{{text(message)}}</pre></details></article></section>
        <section><h4>素材来源 · {{trace.mediaSources?.length||0}}</h4><div v-for="(media,index) in trace.mediaSources||[]" :key="index" class="source-item"><b>{{media.title||media.assetId||media.messageId||'素材'}}</b><p>{{media.authorName||media.senderName||media.authorId||'作者未知'}} · {{media.sentAt||'时间未知'}}</p><small>来源消息 {{media.sourceMessageId||media.messageId||'未知'}} · {{media.relation||'输入素材'}}</small></div><h4>检索记忆 · {{trace.memories?.length||0}}</h4><div v-for="(memory,index) in trace.memories||[]" :key="index" class="source-item">{{memory.text||text(memory)}}</div></section></div>
      <details><summary>展开决策与完整诊断</summary><pre>{{text(trace.decision||{})}}</pre><pre>{{text(trace)}}</pre></details>
    </article><div v-if="!traces.length" class="empty">暂无诊断记录</div>
  </section>
</template>
<style scoped>.trace-card{border-top:1px solid #edf0ed;padding:17px 0}.trace-card header{display:flex;justify-content:space-between;gap:10px;color:#46564e}.trace-card header p,.source-item p{color:#89948e;font-size:12px}.trace-card code{color:#99a49e;font-size:11px}.trace-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.trace-grid h4{font-size:13px;color:#54665c}.context-message,.source-item{padding:11px 0;border-bottom:1px solid #f0f2f0;font-size:12px}.context-heading{display:flex;justify-content:space-between;align-items:center}.relation-pill{color:#497b66;background:#eef5f1;border-radius:12px;padding:3px 8px;font-size:10px}.context-content,.context-segment p{margin:7px 0;white-space:pre-wrap;overflow-wrap:anywhere}.context-message small,.source-item small{color:#929c96}.raw-context{margin-top:8px}.raw-context pre{max-height:260px;overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f7f8f7;padding:12px;border-radius:8px;font-size:11px;color:#59665f}details{margin-top:14px}summary{cursor:pointer;color:#52836e;font-size:12px}@media(max-width:700px){.trace-grid{grid-template-columns:1fr}}</style>
